type NavigationRuntime = ReturnType<typeof createNavigationRuntime>
/** No diagnostic field copy: the empty target forwards to the original view.
 * Closed writes succeed without touching it, so strict finally does not throw.
 * Active Reflect.set errors/failure retain the original strict assignment behavior. */
function createNavigationLeaseView<T extends object>(view: T, isOpen: () => boolean): T {
  return new Proxy<T>(Object.create(Object.getPrototypeOf(view)), {
    get(_target, key) { return Reflect.get(view, key, view) },
    set(_target, key, value) { return isOpen() ? Reflect.set(view, key, value, view) : true },
    ownKeys() { return Reflect.ownKeys(view) },
    getOwnPropertyDescriptor(_target, key) {
      const descriptor = Reflect.getOwnPropertyDescriptor(view, key)
      // The private target has no nonconfigurable fields. Preserve enumeration only.
      return descriptor ? { ...descriptor, configurable: true } : undefined
    }
  })
}

/** One token for one shared diagnostic view. Foreign Owners get private leases. */
export interface NavigationDiagnosticLease { currentToken: object | null }
export function createNavigationDiagnosticLease(): NavigationDiagnosticLease { return { currentToken: null } }
/** Public Map identity stays original; only private runtime mutation is leased. */
function createNavigationLeaseMap<K, V>(view: Map<K, V>, canAccess: () => boolean): Map<K, V> {
  // Iterators verify the lease at each next, so a pre-handoff iterator cannot
  // yield new-owner objects. Current values retain their actual object identity.
  const iterate = <T>(read: () => IterableIterator<T>): IterableIterator<T> => {
    let iterator: IterableIterator<T> | undefined
    return { next() {
      if (!canAccess()) return { done: true, value: undefined }
      iterator ??= read()
      return iterator.next()
    }, [Symbol.iterator]() { return this } }
  }
  let proxy: Map<K, V>
  const clear = () => { if (canAccess()) view.clear() }
  const remove = (entry: K) => canAccess() ? view.delete(entry) : false
  const set = (entry: K, value: V) => canAccess() ? view.set(entry, value) : proxy
  const get = (entry: K) => canAccess() ? view.get(entry) : undefined
  const has = (entry: K) => canAccess() ? view.has(entry) : false
  const keys = () => iterate(() => view.keys())
  const values = () => iterate(() => view.values())
  const entries = () => iterate(() => view.entries())
  const forEach = (callback: (value: V, key: K, map: Map<K, V>) => void, receiver?: unknown) => {
    if (canAccess()) view.forEach((value, key) => { if (canAccess()) callback.call(receiver, value, key, view) })
  }
  proxy = new Proxy(view, { get(target, key) {
    if (key === 'size') return canAccess() ? view.size : 0
    if (key === 'clear') return clear
    if (key === 'delete') return remove
    if (key === 'set') return set
    if (key === 'get') return get
    if (key === 'has') return has
    if (key === 'keys') return keys
    if (key === 'values') return values
    if (key === 'entries' || key === Symbol.iterator) return entries
    if (key === 'forEach') return forEach
    const value = Reflect.get(target, key, target)
    return typeof value === 'function' ? value.bind(target) : value
  } })
  return proxy
}

