/** 结构说明（自动提取）：updateNavigation；输入 entities、fixedDelta、nowSeconds；直接调用 sort、entities.filter、allAgents.slice、Math.max、activeAgents.reduce 等；写入 performanceRuntimeState.spatialEntries、navigationProfile.activeAgents、navigationProfile.droppedAgents、navigationProfile.avoidancePairs 等；包含循环处理。 */ function updateNavigation(entities: Entity[], fixedDelta: number, nowSeconds: number): void {
