/** 结构说明（自动提取）：clearNavigationData；输入 regionUuid；直接调用 cancelNavigationBake、grids.delete、grids.clear、navigationDebugPaths.clear、nextRepath.clear 等；写入 navigationBakeState.artifactHash、navigationBakeState.error；包含循环处理。 */ function clearNavigationData(regionUuid?: string): void {
  cancelNavigationBake(); navigationBakeState.artifactHash = ''; navigationBakeState.error = ''
  if (regionUuid) { for (const [key, grid] of grids) if (grid.regionUuid === regionUuid) grids.delete(key) } else grids.clear()
